1	import { BadRequestException, Body, Controller, Get, Post, Req, UseGuards } from '@nestjs/common';
2	import { JwtGuard } from '../auth/jwt.guard';
3	import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
4	import { SupabaseService } from '../supabase/supabase.service';
5	import { GeocodingService } from '../motoboy/geocoding.service';
6	import { PlanosService } from '../planos/planos.service';
7	import { UsuariosService } from '../usuarios/usuarios.service';
8	
9	@Controller('restaurante')
10	export class OnboardingController {
11	  constructor(
12	    private supabase: SupabaseService,
13	    private geocoding: GeocodingService,
14	    private planos: PlanosService,
15	    private usuarios: UsuariosService,
16	  ) {}
17	
18	  // Público (sem guard) — a wizard de cadastro mostra os planos antes do
19	  // usuário logar/criar conta, pra ele escolher já na primeira etapa.
20	  @Get('planos-disponiveis')
21	  planosDisponiveis() {
22	    return this.planos.listarPlanosAtivos('saas');
23	  }
24	
25	  private normalizarDigitos(v?: string | null): string | null {
26	    const d = (v ?? '').replace(/\D/g, '');
27	    return d || null;
28	  }
29	
30	  private normalizarEmail(v?: string | null): string | null {
31	    const e = (v ?? '').trim().toLowerCase();
32	    return e || null;
33	  }
34	
35	  // Checa CNPJ/WhatsApp/email contra os demais restaurantes (excluindo o
36	  // próprio, pra reenvio do mesmo formulário não acusar conflito consigo
37	  // mesmo). CNPJ é opcional — null nunca conflita (UNIQUE do Postgres também
38	  // trata assim).
39	  private async checarDuplicados(
40	    restaurantId: number,
41	    valores: { cnpj: string | null; whatsapp: string | null; email: string | null },
42	  ) {
43	    const ors: string[] = [];
44	    if (valores.cnpj) ors.push(`cnpj.eq.${valores.cnpj}`);
45	    if (valores.whatsapp) ors.push(`whatsapp.eq.${valores.whatsapp}`);
46	    if (valores.email) ors.push(`email.eq.${valores.email}`);
47	    if (!ors.length) return { cnpj: false, whatsapp: false, email: false };
48	
49	    const { data, error } = await this.supabase.client
50	      .from('restaurants')
51	      .select('id, cnpj, whatsapp, email')
52	      .or(ors.join(','))
53	      .neq('id', restaurantId);
54	    if (error) throw error;
55	
56	    const conflita = (campo: 'cnpj' | 'whatsapp' | 'email', valor: string | null) =>
57	      !!valor && (data ?? []).some((r: any) => r[campo] === valor);
58	
59	    return {
60	      cnpj: conflita('cnpj', valores.cnpj),
61	      whatsapp: conflita('whatsapp', valores.whatsapp),
62	      email: conflita('email', valores.email),
63	    };
64	  }
65	
66	  // Checagem em tempo real usada pela wizard (passos "business"/"contact")
67	  // pra avisar de duplicidade assim que o usuário sai do campo, em vez de só
68	  // no /finalizar (último passo) — bem tarde pra descobrir que o CNPJ digitado
69	  // 3 passos atrás já está em uso.
70	  @Post('verificar-disponibilidade')
71	  @UseGuards(RestaurantOwnerGuard)
72	  async verificarDisponibilidade(
73	    @Req() req: any,
74	    @Body() body: { cnpj?: string; whatsapp?: string; email?: string },
75	  ) {
76	    const restaurantId: number = req.restaurantId;
77	    const duplicados = await this.checarDuplicados(restaurantId, {
78	      cnpj: this.normalizarDigitos(body.cnpj),
79	      whatsapp: this.normalizarDigitos(body.whatsapp),
80	      email: this.normalizarEmail(body.email),
81	    });
82	    return {
83	      cnpj_disponivel: !duplicados.cnpj,
84	      whatsapp_disponivel: !duplicados.whatsapp,
85	      email_disponivel: !duplicados.email,
86	    };
87	  }
88	
89	  // 1ª fase do cadastro: cria a loja só com nome + assinatura do plano
90	  // escolhido, e cobra a fatura do período atual na hora se o plano não tiver
91	  // trial. O resto do formulário (endereço, horários, tipo...) só é liberado
92	  // na wizard depois que essa fatura confirmar paga (ou, se for plano com
93	  // trial, direto). Idempotente: se o usuário já tem restaurante (reload no
94	  // meio do checkout), retorna o estado atual em vez de criar de novo.
95	  @Post('registrar-inicial')
96	  @UseGuards(JwtGuard)
97	  async registrarInicial(@Req() req: any, @Body() body: { name?: string; plano_id?: number }) {
98	    const userId: string = req.userId;
99	
100	    const { data: existing } = await this.supabase.client
101	      .from('restaurants')
102	      .select('id, name')
103	      .eq('user_id', userId)
104	      .maybeSingle();
105	
106	    let restaurant = existing;
107	    let precisaAssinar = false;
108	
109	    if (!restaurant) {
110	      if (!body.name?.trim()) throw new BadRequestException('Nome do estabelecimento é obrigatório.');
111	      if (!body.plano_id) throw new BadRequestException('Selecione um plano para continuar.');
112	
113	      // Motoboy e dono de estabelecimento precisam ser contas separadas — essa
114	      // conta já está vinculada a um cadastro de motoboy (ver regra espelhada em
115	      // MotoboyAuthService.exigirContaSemRestaurante).
116	      const { data: motoboyVinculado } = await this.supabase.client
117	        .from('motoboys')
118	        .select('id')
119	        .eq('user_id', userId)
120	        .maybeSingle();
121	      if (motoboyVinculado) {
122	        throw new BadRequestException('Esta conta já está cadastrada como motoboy. Cadastre o estabelecimento usando outra conta.');
123	      }
124	
125	      const slug = body.name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
126	
127	      const { data: novo, error } = await this.supabase.client
128	        .from('restaurants')
129	        .insert({ name: body.name, user_id: userId, slug })
130	        .select('id, name')
131	        .single();
132	      if (error) throw error;
133	      restaurant = novo;
134	      precisaAssinar = true;
135	    } else if (body.plano_id) {
136	      // Já tem loja (voltou nesse passo, ou reload) — só reassina se o plano
137	      // escolhido agora for DIFERENTE do que já está na assinatura. Sem essa
138	      // checagem, trocar de plano na wizard e clicar Continuar de novo
139	      // ignorava a nova escolha e reaproveitava fatura/trial do plano antigo.
140	      const { assinatura } = await this.planos.buscarAssinaturaPorRestaurante(restaurant.id);
141	      precisaAssinar = assinatura.plano_id !== body.plano_id;
142	
143	      if (precisaAssinar) {
144	        // Role só eleva pra restaurant_owner no /finalizar — se ainda é
145	        // 'customer', o usuário está só comparando planos, nada foi pago.
146	        // Cancela fatura pendente do plano anterior pra não ficar presa
147	        // bloqueando o plano novo escolhido (ex: trial). Restrito a esse
148	        // estado pra não deixar um dono já pagante cancelar dívida real só
149	        // reenviando outro plano_id nesse endpoint.
150	        const { data: perfil } = await this.supabase.client
151	          .from('user_profiles').select('role').eq('id', userId).maybeSingle();
152	        if (perfil?.role !== 'restaurant_owner') {
153	          await this.supabase.client
154	            .from('plano_faturas')
155	            .update({ status: 'cancelada', atualizado_em: new Date().toISOString() })
156	            .eq('assinatura_id', assinatura.id)
157	            .in('status', ['pendente', 'vencida']);
158	        }
159	      }
160	    }
161	
162	    let status: { fatura_pendente_id: number | null };
163	    if (precisaAssinar) {
164	      // precisaAssinar só fica true quando body.plano_id já foi validado como
165	      // presente (loja nova) ou veio no body pra decidir a troca (loja existente).
166	      const planoId = body.plano_id as number;
167	      const plano = await this.planos.buscarPlano(planoId);
168	      await this.planos.atribuirAssinatura({ restaurantId: restaurant.id }, planoId);
169	
170	      // Sem trial: gera (forçado) a fatura do período atual pra cobrar já no
171	      // cadastro. Com trial, não força nada — fica pra próxima renovação natural.
172	      const temTrial = (plano.trial_dias ?? 0) > 0;
173	      status = await this.planos.sincronizarPeriodo({ restaurantId: restaurant.id }, !temTrial);
174	    } else {
175	      status = await this.planos.sincronizarPeriodo({ restaurantId: restaurant.id });
176	    }
177	
178	    if (!status.fatura_pendente_id) {
179	      // Assinou plano com trial (sem cobrança) — já vira dono aqui, sem esperar
180	      // o resto da wizard (endereço, horários...). Restrito a precisaAssinar pra
181	      // não elevar num reload de loja com assinatura cancelada (que também cai
182	      // em fatura_pendente_id null, mas não é uma assinatura ativa de verdade).
183	      if (precisaAssinar) await this.usuarios.sincronizarVinculoDono(restaurant.id, userId);
184	      return { restaurant, precisa_pagamento: false, fatura: null };
185	    }
186	
187	    const fatura = await this.planos.buscarFaturaDoRestaurante(restaurant.id, status.fatura_pendente_id);
188	    return { restaurant, precisa_pagamento: true, fatura };
189	  }
190	
191	  // 2ª fase: completa o cadastro (endereço, horários, tipo de estabelecimento)
192	  // e eleva o role pra restaurant_owner — só chamada depois que a wizard
193	  // liberou o formulário (plano pago ou em trial).
194	  @Post('finalizar')
195	  @UseGuards(RestaurantOwnerGuard)
196	  async finalizar(
197	    @Req() req: any,
198	    @Body()
199	    body: {
200	      name?: string;
201	      address?: string;
202	      state?: string;
203	      city?: string;
204	      neighborhood?: string;
205	      cep?: string;
206	      business_hours?: object;
207	      type_id?: number;
208	      cnpj?: string;
209	      whatsapp?: string;
210	      email?: string;
211	    },
212	  ) {
213	    const restaurantId: number = req.restaurantId;
214	    const userId: string = req.userId;
215	
216	    const cnpjNorm = this.normalizarDigitos(body.cnpj);
217	    const whatsappNorm = this.normalizarDigitos(body.whatsapp);
218	    const emailNorm = this.normalizarEmail(body.email);
219	
220	    // Última barreira antes de gravar — a wizard já checou isso passo a passo
221	    // (verificar-disponibilidade), mas dois cadastros concorrentes com o mesmo
222	    // CNPJ/WhatsApp/email só se pegam aqui (e na UNIQUE constraint do banco).
223	    const duplicados = await this.checarDuplicados(restaurantId, {
224	      cnpj: cnpjNorm,
225	      whatsapp: whatsappNorm,
226	      email: emailNorm,
227	    });
228	    const mensagens: string[] = [];
229	    if (duplicados.cnpj) mensagens.push('Este CNPJ já está cadastrado em outro estabelecimento.');
230	    if (duplicados.whatsapp) mensagens.push('Este WhatsApp já está cadastrado em outro estabelecimento.');
231	    if (duplicados.email) mensagens.push('Este email já está cadastrado em outro estabelecimento.');
232	    if (mensagens.length) throw new BadRequestException(mensagens.join(' '));
233	
234	    const campos: Record<string, any> = { updated_at: new Date().toISOString() };
235	    if (body.name !== undefined) campos.name = body.name;
236	    if (body.address !== undefined) campos.address = body.address;
237	    if (body.state !== undefined) campos.state = body.state;
238	    if (body.city !== undefined) campos.city = body.city;
239	    if (body.neighborhood !== undefined) campos.neighborhood = body.neighborhood;
240	    if (body.cep !== undefined) campos.cep = body.cep ? body.cep.replace(/\D/g, '') : null;
241	    if (body.business_hours !== undefined) campos.business_hours = body.business_hours;
242	    if (body.type_id !== undefined) campos.type_id = body.type_id;
243	    if (body.cnpj !== undefined) campos.cnpj = cnpjNorm;
244	    if (body.whatsapp !== undefined) campos.whatsapp = whatsappNorm;
245	    if (body.email !== undefined) campos.email = emailNorm;
246	
247	    const { data: restaurant, error } = await this.supabase.client
248	      .from('restaurants')
249	      .update(campos)
250	      .eq('id', restaurantId)
251	      .select()
252	      .single();
253	    if (error) {
254	      // Última rede de segurança contra corrida (dois cadastros com o mesmo
255	      // CNPJ/WhatsApp/email confirmando entre a checagem acima e este update).
256	      if ((error as any).code === '23505') {
257	        throw new BadRequestException('CNPJ, WhatsApp ou email já cadastrado em outro estabelecimento.');
258	      }
259	      throw error;
260	    }
261	
262	    // Geocodifica em background (best-effort) — sem isso o restaurante nunca aparece no
263	    // filtro por raio/km da home até o dono re-salvar o endereço em Config manualmente.
264	    if (restaurant.address || restaurant.cep) {
265	      const texto = [restaurant.address, restaurant.neighborhood, restaurant.city, restaurant.state, restaurant.cep]
266	        .filter(Boolean).join(', ');
267	      this.geocoding.geocodeEndereco(texto).then((coords) => {
268	        if (!coords) return;
269	        return this.supabase.client
270	          .from('restaurants')
271	          .update({ lat: coords.lat, lng: coords.lng, geocoded_at: new Date().toISOString(), geocode_falhou: false })
272	          .eq('id', restaurant.id);
273	      }).catch(() => {});
274	    }
275	
276	    // Eleva role para restaurant_owner — propaga erro em vez de engolir, senão
277	    // o endpoint responde 200 mesmo com o vínculo quebrado (causa raiz de um
278	    // bug em produção onde o dono nunca via o botão do painel).
279	    await this.usuarios.sincronizarVinculoDono(restaurantId, userId);
280	
281	    return { restaurant };
282	  }
283	}
