6	const ForgotPasswordModal = ({ 
7	  isOpen = false,
8	  onClose = () => {},
9	  onResetPassword = () => {},
10	  primaryColor = '#2563EB',
11	  className = ''
12	}) => {
13	  const [email, setEmail] = useState('');
14	  const [error, setError] = useState('');
15	  const [loading, setLoading] = useState(false);
16	  const [sent, setSent] = useState(false);
17	
18	  const handleSubmit = async (e) => {
19	    e?.preventDefault();
20	    
21	    if (!email?.trim()) {
22	      setError('Email é obrigatório');
23	      return;
24	    }
25	
26	    if (!/\S+@\S+\.\S+/?.test(email)) {
27	      setError('Email inválido');
28	      return;
29	    }
30	
31	    setLoading(true);
32	    setError('');
33	
34	    try {
35	      await onResetPassword(email);
36	      setSent(true);
37	    } catch (error) {
38	      setError('Erro ao enviar email de recuperação');
39	    } finally {
40	      setLoading(false);
41	    }
42	  };
43	
44	  const handleClose = () => {
45	    setEmail('');
46	    setError('');
47	    setSent(false);
48	    onClose();
49	  };
50	
51	  const handleBackdropClick = (e) => {
52	    if (e?.target === e?.currentTarget) {
53	      handleClose();
54	    }
55	  };
56	
57	  if (!isOpen) return null;
58	
59	  return (
60	    <div 
61	      className={`fixed inset-0 z-200 flex items-center justify-center p-4 bg-black bg-opacity-50 animate-fade-in ${className}`}
62	      onClick={handleBackdropClick}
63	    >
64	      <div className="w-full max-w-md bg-card rounded-lg shadow-lg animate-slide-up elevation-3">
65	        {/* Header */}
66	        <div className="flex items-center justify-between p-6 border-b border-border">
67	          <h2 className="text-xl font-semibold text-foreground">
68	            {sent ? 'Email Enviado' : 'Recuperar Senha'}
69	          </h2>
70	          <button
71	            onClick={handleClose}
72	            className="p-1 rounded-lg hover:bg-muted transition-colors duration-200"
73	            aria-label="Close modal"
74	          >
75	            <Icon name="X" size={20} className="text-muted-foreground" />
76	          </button>
77	        </div>
78	
79	        {/* Content */}
80	        <div className="p-6">
81	          {sent ? (
82	            <div className="text-center space-y-4">
83	              <div 
84	                className="w-16 h-16 mx-auto mb-4 rounded-full flex items-center justify-center"
85	                style={{ backgroundColor: `${primaryColor}20` }}
86	              >
87	                <Icon name="Mail" size={32} style={{ color: primaryColor }} />
88	              </div>
89	              
90	              <div className="space-y-2">
91	                <p className="text-sm text-muted-foreground">
92	                  Enviamos um link de recuperação para:
93	                </p>
94	                <p className="text-sm font-medium text-foreground">
95	                  {email}
96	                </p>
97	                <p className="text-xs text-muted-foreground">
98	                  Verifique sua caixa de entrada e spam
99	                </p>
100	              </div>
101	
102	              <Button
103	                onClick={handleClose}
104	                fullWidth
105	                style={{ backgroundColor: primaryColor }}
106	              >
107	                Entendi
108	              </Button>
109	            </div>
110	          ) : (
111	            <form onSubmit={handleSubmit} className="space-y-4">
112	              <div className="text-center mb-4">
113	                <p className="text-sm text-muted-foreground">
114	                  Digite seu email para receber um link de recuperação de senha
115	                </p>
116	              </div>
117	
118	              <Input
119	                label="Email"
120	                type="email"
121	                value={email}
122	                onChange={(e) => {
123	                  setEmail(e?.target?.value);
124	                  if (error) setError('');
125	                }}
126	                placeholder="Digite seu email"
127	                error={error}
128	                required
129	              />
130	
